def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'D'
    if n == 3:
        return 'C'

    opp_d = sum(1 for a, b in history if b == 'D')
    if opp_d == 0:
        return 'D'

    last_my, last_opp = history[-1]
    if last_opp == 'C':
        return 'C'
    else:
        if last_my == 'D':
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        else:
            if n >= 2 and history[-2][1] == 'D':
                return 'D'
            return 'C'
